// retiredPostTodoHookCommand is the post-todo command older CLIs installed.
// It is no longer installed, and an install prunes it, but its subcommand stays
// registered and records nothing, so a checkout that still carries it runs
// only Entire.
func retiredPostTodoHookCommand() string {
	return agent.WrapProductionSilentHookCommand("entire hooks claude-code " + HookNamePostTodo)
}

// EntireHookCommands returns the exact commands Entire installs, by event,
// plus the retired post-todo command older CLIs installed, so review still
// recognizes a teammate's config that has not been re-enabled yet as Entire's
// own. Callers must match whole commands: a prefix would accept
// "entire hooks ...; curl".
func EntireHookCommands() map[string][]string {
	out := make(map[string][]string)
	for _, h := range entireSimpleHooks() {
		out[h.hookType] = append(out[h.hookType], h.command)
	}
	preTask, postTask := entireToolUseHookCommands()
	out["PreToolUse"] = append(out["PreToolUse"], preTask)
	out["PostToolUse"] = append(out["PostToolUse"], postTask, retiredPostTodoHookCommand())
	return out
}

// installHookEntries mutates rawHooks in place to ensure every Entire hook is
// present with its timeout, migrating stale entries (from older CLI versions
// or, when force is set, any current Entire hook) first. Returns the number of
// hooks newly added, whether any stale entry was dropped, and whether any entry
// gained a timeout (see the staleDropped comment at its InstallHooks call site
// for why either forces a write on its own).
func installHookEntries(rawHooks map[string]json.RawMessage, force bool) (count int, staleDropped, timeoutsSet bool) {
	var preToolUse, postToolUse []ClaudeHookMatcher
	parseHookType(rawHooks, "PreToolUse", &preToolUse)
	parseHookType(rawHooks, "PostToolUse", &postToolUse)

	// The "simple" hook types all share one shape: a single Entire command
	// under one matcher (empty for most), alone in its hook type. Handling
	// them data-driven (rather than one parse/strip/add/marshal block per type)
	// keeps this function's complexity from growing linearly with each new
	// simple hook type Entire registers.
	simpleHooks := entireSimpleHooks()
	simpleMatchers := make(map[string][]ClaudeHookMatcher, len(simpleHooks))
	for _, h := range simpleHooks {
		var m []ClaudeHookMatcher
		parseHookType(rawHooks, h.hookType, &m)
		simpleMatchers[h.hookType] = m
	}

	// If force is true, remove all existing Entire hooks first
	if force {
		for _, h := range simpleHooks {
			simpleMatchers[h.hookType] = removeEntireHooks(simpleMatchers[h.hookType])
		}
		preToolUse = removeEntireHooksFromMatchers(preToolUse)
		postToolUse = removeEntireHooksFromMatchers(postToolUse)
	}

	// not parse never reaches here — AreHooksInstalled fails on it, so
	// GetAgentsWithHooksInstalled leaves it out — which leaves only write
	// failures, and printing "stale rule" for those would name the wrong
	// problem. (That a broken config goes unreported at all is a separate,
	// pre-existing gap: agentHookState.unchecked has no consumer.)
	repairInstalledAgents(cmd, "could not remove retired deny rule",
		// One pass: Repair reports whether it found the rule, so a separate
		// detect call would only read and parse the same file twice.
		agent.RepairRetiredMetadataDenyRule,
		func(w io.Writer, ag agent.Agent) {
			fmt.Fprintf(w, "%s permissions: STALE RULE\n", ag.Type())
			fmt.Fprintf(w, "  A retired Entire deny rule (%s) was still present.\n", agent.MetadataDenyRule)
			fmt.Fprintln(w, "  It makes ordinary commands (a recursive grep from the repo root, or any")
			fmt.Fprintln(w, "  command naming that path) need manual approval, and it no longer protects")
			fmt.Fprintln(w, "  anything: the file it guarded is removed once a session is condensed.")
			fmt.Fprintln(w, "  ✓ Fixed: rule removed (your other deny rules are untouched).")
		})
}

// checkHookTimeouts gives Entire's hooks the timeouts a config written by an
// older CLI lacks, so the agent's own default does not apply instead: a longer
// one lets a stalled `entire` launch block the agent, and a shorter one (agy's
// 30s on Stop) kills a turn-end hook before it saves session state. It repairs without asking for the reason
// checkRetiredDenyRule does: it only sets a timeout on a hook Entire wrote that
// has none, so nothing the user chose is touched. As there, a repair error is
// logged rather than printed.
func checkHookTimeouts(cmd *cobra.Command) {
	repairInstalledAgents(cmd, "could not add missing hook timeouts",
		func(ctx context.Context, ag agent.Agent) (bool, error) {
			repairer, ok := agent.AsHookTimeoutRepairer(ag)
			if !ok {
				return false, nil
			}
			return repairer.RepairHookTimeouts(ctx)
		},
		func(w io.Writer, ag agent.Agent) {
			fmt.Fprintf(w, "%s hooks: MISSING TIMEOUTS\n", ag.Type())
			fmt.Fprintln(w, "  Some Entire hooks had no timeout, so the agent applied its own default,")
			fmt.Fprintln(w, "  which can block the agent too long or stop a hook before it finishes.")
			fmt.Fprintln(w, "  ✓ Fixed: timeouts added (your own hooks and timeouts are untouched).")
		})
}

// repairInstalledAgents runs repair, which fixes an agent's config without
// asking, on every agent with hooks installed here. For each config it changed,
// report says what was fixed, and the user is told the settings file changed:
	HasStaleManagedHooks(ctx context.Context) bool
}

// HookTimeoutRepairer is implemented by agents whose Entire hooks carry
// timeouts that configs written by older CLIs lack. `entire doctor` runs the
// repair without asking, because a user who already enabled Entire has no
// reason to run enable again. The repair must only give Entire's own hooks a
// missing timeout and leave everything the user chose as it is.
type HookTimeoutRepairer interface {
	Agent

	// RepairHookTimeouts adds the missing timeouts and reports whether it
	// rewrote the hook config. An absent config is not an error.
	RepairHookTimeouts(ctx context.Context) (bool, error)
}

// EffectiveHookDiagnostics marks agents whose effective hook state is reported
// by an agent-owned diagnostic surface rather than generic freshness output.
type EffectiveHookDiagnostics interface {
	Agent
	OwnsEffectiveHookDiagnostics()

